"""Generate the static professional website. Standard-library Python only."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parents[1]
BASE = 'https://acnash.github.io/'
SCHOLAR = 'https://scholar.google.com/citations?user=MZcEEh0AAAAJ&amp;hl=en'
MANUSCRIPT = BASE + 'Strange-Matter-Engine/'
NAV = [('index.html', 'Home'), ('experience.html', 'Experience'), ('publications.html', 'Selected publications'), ('education.html', 'Education'), ('research.html', 'Research & projects')]

def profiles():
    return f'''<div class="profiles"><a href="https://www.linkedin.com/in/dr-anthony-nash-7050078/">LinkedIn</a><a href="{SCHOLAR}">Google Scholar</a><a href="https://github.com/acnash">GitHub</a><a href="https://orcid.org/0000-0001-8212-0302">ORCID</a></div>'''

def contact():
    return '''<section class="contact-panel" id="contact"><h2>Contact</h2><p>I welcome conversations about fractional scientific leadership, advisory work and hands-on research contracts. Based in Warwickshire, England, I can work remotely with organisations in the UK and internationally.</p><a class="button" href="mailto:info@acnash.co.uk">info@acnash.co.uk</a></section>'''

def video():
    return '''<figure><video controls autoplay muted loop playsinline preload="metadata" aria-label="Four recorded molecular space-time trajectories" aria-describedby="trajectory-caption"><source src="assets/molecular-space-time-four-trajectories.mp4" type="video/mp4"><p><a href="assets/molecular-space-time-four-trajectories.mp4">Watch the molecular space-time trajectories.</a></p></video><figcaption id="trajectory-caption">Four recorded molecular space-time trajectories over 1,000 cellular automaton generations. Colours represent numerical atom states. Rotation reveals the molecular structure as the trace progresses downwards.</figcaption></figure>'''

def page(filename, title, description, content):
    nav = ''.join(f'<a href="{path}"'+(' aria-current="page"' if path == filename else '')+f'>{label}</a>' for path,label in NAV)
    canonical = BASE if filename == 'index.html' else BASE + filename
    html = f'''<!doctype html>
<html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="google-site-verification" content="pUQUqC7unUI2fWtByzZLzYiBhMAr6poU5VL-ZXD7ToI">
<title>{escape(title)} | Dr Anthony Nash</title><meta name="description" content="{escape(description, quote=True)}">
<link rel="canonical" href="{canonical}"><link rel="stylesheet" href="assets/site.css?v=20261117-plum">
<meta property="og:title" content="{escape(title, quote=True)} | Dr Anthony Nash"><meta property="og:description" content="{escape(description, quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}">
</head><body><a class="skip" href="#main">Skip to content</a>
<header class="site-header"><div class="wrap"><div class="topline"><a class="brand" href="index.html">Dr Anthony Nash<small>Scientific leadership &amp; computational chemistry</small></a><a class="contact-link" href="mailto:info@acnash.co.uk">Discuss a collaboration</a></div><nav class="primary-nav" aria-label="Main navigation">{nav}</nav></div></header>
<main class="wrap" id="main">{content}</main>
<footer class="site-footer"><div class="wrap"><p>Anthony Nash · Warwickshire, England<br>Scientific consultancy, advisory and collaboration</p>{profiles()}</div></footer>
</body></html>'''
    (ROOT / filename).write_text(html, encoding='utf-8')

home = f'''
<section class="hero"><div><p class="eyebrow">Scientific consultancy · Advisory · Collaboration</p><h1>Scientific leadership and computational chemistry.</h1><p class="lead">I am Anthony Nash, a scientist and senior consultant working across computational chemistry, drug discovery and scientific technology.</p><p>I bring almost two decades of experience across academia, industry and scientific start-ups. I help organisations define research priorities, develop computational methods and coordinate the delivery of science.</p><div class="actions"><a class="button" href="mailto:info@acnash.co.uk">Discuss your project</a><a class="button secondary" href="experience.html">Explore my experience</a></div></div><aside aria-label="Professional overview"><h2>Current role and consultancy</h2><p>I work with scientific teams, founders and senior leaders, combining hands-on investigation with practical scientific direction.</p><dl><dt>Current role</dt><dd>Interim Chief Scientific Officer<br>WYW Quantum</dd><dt>Ways of working</dt><dd>Fractional leadership<br>Scientific advice<br>Part-time and project contracts</dd><dt>Based in</dt><dd>Warwickshire, England</dd></dl></aside></section>
<section class="section" id="consulting"><h2>Consultancy services</h2><div class="columns"><div><span class="number">01 / LEADERSHIP</span><h3>Research planning and team coordination</h3><p>Define research priorities, plan methodologies and coordinate multidisciplinary teams, with clear connections between scientific objectives and practical work.</p></div><div><span class="number">02 / RESEARCH</span><h3>Computational chemistry and drug discovery</h3><p>Contribute directly to molecular simulation, quantum chemistry, structural biology and physics-based drug discovery, supported by software engineering experience.</p></div><div><span class="number">03 / ADVICE</span><h3>Scientific advice and communication</h3><p>Explain scientific findings, contribute to investment materials and help founders and leadership teams assess research options and technical priorities.</p></div></div></section>
<section class="section" id="background"><div class="section-heading"><h2>Professional background</h2><a href="experience.html">View experience →</a></div><div class="reading"><p>My career connects research at Oxford University, University College London and Imperial College London with roles in scientific start-ups. At Oxford, I combined clinical epidemiology and drug discovery to identify a potential treatment for migraine, contributing to research underpinning Human Centric Drug Discovery.</p><p>I also tutor and contribute to metalloprotease and extracellular-matrix drug discovery projects through consultancy with Arizona State University. My PhD at the University of Warwick and earlier work in artificial intelligence and software engineering underpin this combination of scientific and computational practice.</p></div></section>
<section class="section" id="manuscript"><div class="section-heading"><h2>Featured independent publication</h2><a href="publications.html">Selected journal publications →</a></div><div class="feature"><div><p class="meta">Anthony Nash · 2026 · Preprint</p><h3><a href="{MANUSCRIPT}">Molecular Space-Time: Emergent Prediction from Local Interactions in an Evolved Graph Cellular Automaton</a></h3><p>A study of how information passed between bonded atoms can produce predictive features and complex dynamics. The OpenADMET CYP Inhibition Challenge provides the predictive testbed.</p><div class="actions"><a href="{MANUSCRIPT}">Read the abstract</a><a href="{MANUSCRIPT}molecular-space-time.pdf">Manuscript PDF</a></div></div>{video()}</div><p style="margin-top:24px"><a href="{SCHOLAR}">Browse all publications on Google Scholar</a></p></section>
<section class="section" id="research"><div class="section-heading"><h2>Research interests and projects</h2><a href="research.html">Explore the research →</a></div><p class="reading">My interests span theoretical biophysics, molecular and quantum chemistry, metalloproteases and complex systems. Current projects include <a href="https://github.com/acnash/mmp1-collagen-oi-adaptive-md">collagen remodelling in osteogenesis imperfecta</a> and <a href="https://github.com/acnash/Strange-Matter-Engine">molecular graph cellular automata</a>.</p></section>
{contact()}'''

def role(title, organisation, paragraphs, bullets=(), note=''):
    return f'''<article class="role"><div><h3>{title}</h3><p class="organisation">{organisation}</p>{f'<p class="role-note">{note}</p>' if note else ''}</div><div>{''.join(f'<p>{p}</p>' for p in paragraphs)}{('<ul>'+''.join(f'<li>{b}</li>' for b in bullets)+'</ul>') if bullets else ''}</div></article>'''

experience = '''<header class="page-intro"><h1>Professional experience</h1><p class="lead">I combine scientific leadership with hands-on computational research, supporting organisations from research planning and method development through to interpretation and communication.</p></header><h2 class="section-label">Scientific start-ups and consultancy</h2>'''
experience += role('Interim Chief Scientific Officer','WYW Quantum', ['I coordinate the implementation and delivery of science at the interface between advanced quantum chemistry, artificial intelligence and quantum computing.'], ['Translate scientific objectives into research plans and methodologies.','Coordinate scientific teams and present findings to collaborators and senior stakeholders.','Contribute scientific content to investment pitch decks and communicate the evidence behind research programmes.'], 'Current role')
experience += role('Consultant','Deep Mirror',['Computational chemistry and physics-based modelling for drug discovery, drawing on structural biology and practical computational methods.'])
experience += role('Principal Scientist','Kuano',['Computational chemistry and physics-based modelling, including classical physics and molecular-mechanics approaches within drug discovery pipelines.'])
experience += role('Digital Health and Cheminformatics Researcher','Human Centric Drug Discovery',['Work connecting clinical epidemiology, digital health and drug discovery. My Oxford research identifying a potential treatment for migraine contributed to the research underpinning this Oxford University spinout.'])
experience += role('Digital Health Research Consultant','Crystal Health',['Scientific consultancy in digital health, bringing together research experience, data analysis and computational approaches.'])
experience += '<h2 class="section-label">University research and collaboration</h2>'
experience += role('Consultancy and tutoring','Arizona State University',['I tutor and contribute to drug discovery projects focused on metalloproteases and the human extracellular matrix, connecting molecular structure and dynamics with questions about enzyme function.'])
experience += role('Postdoctoral research','Oxford University',['Neuroscience drug discovery combining clinical epidemiology and computational research. This work included investigating therapeutic opportunities for migraine and research underpinning Human Centric Drug Discovery.'])
experience += role('Postdoctoral research','University College London',['Computational modelling of advanced glycation end products and the hallmarks of ageing, with particular attention to collagen structure, cross-linking and extracellular-matrix properties.'])
experience += role('Postdoctoral research','Imperial College London',['Computational modelling of cytochrome P450 enzymes in fungal pathogens and research into antifungal resistance. My first-author MARDy publication describes a curated resource for antifungal resistance mechanisms.'])
experience += '<section class="section"><h2>Software engineering</h2><p class="reading">My earlier career in corporate software engineering complements my research. I work across the formulation of a scientific question, implementation of computational methods and interpretation of the resulting evidence, and can contribute both as a senior adviser and as a practising scientist.</p><a href="education.html">Education →</a></section>' + contact()

education = '''<header class="page-intro"><h1>Education</h1><p class="lead">My training brings together computational chemistry, chemical biology and an early interest in artificial intelligence and natural computing.</p></header><article class="education-record"><p class="eyebrow">University of Warwick · 2013</p><h2>PhD</h2><p class="meta">Computational chemistry and chemical biology</p><p>My doctoral work explored membrane-protein structure and interactions through chemical biology and computational approaches. It provided the foundation for my subsequent research in molecular simulation and theoretical biophysics.</p></article><article class="education-record"><p class="eyebrow">University of Warwick · 2009–2010</p><h2>MSc Mathematical Biology and Biophysical Chemistry</h2><p>Molecular Organisation and Assembly in Cells Doctoral Training Centre, Department of Chemistry.</p></article><article class="education-record"><p class="eyebrow">University of Birmingham · 2003–2004</p><h2>MSc Natural Computing</h2><p>Department of Computer Science.</p></article><article class="education-record"><p class="eyebrow">Undergraduate study</p><h2>Artificial intelligence</h2><p>My first degree was in artificial intelligence. I focused particularly on unconventional computing, complex systems and nature-inspired computing, interests that continue to inform my independent research.</p></article><section class="section reading"><h2>Postdoctoral research and software engineering</h2><p>Professional software engineering and subsequent postdoctoral research extended this foundation into computational chemistry, drug discovery and the analysis of biological systems.</p><div class="actions"><a href="experience.html">Professional experience →</a><a href="research.html">Research interests →</a></div></section>''' + contact()

# Selected from the public Scholar profile; titles, authorship and dates checked
