('2026','Nature Communications','Co-author','Harlow CE, Uzochukwu E, Fernando HA, et al. (including Anthony Nash).','GWAS of extended prescription analgesic use identifies genetic loci in chronic pain','10.1038/s41467-026-71434-8','Uses prescription-based pain phenotypes and large biobank datasets to investigate the genetics of chronic pain.'),
('2018','Bioinformatics','First author','Nash A, Sewell T, Farrer RA, Abdolrasouli A, Shelton JMG, Fisher MC, Rhodes J.','MARDy: Mycology Antifungal Resistance Database','10.1093/bioinformatics/bty321','A curated resource connecting antifungal drugs with reported genetic mechanisms of resistance.'),
('2019','Matrix Biology Plus','First author','Nash A, Notou M, Lopez-Clavijo AF, Bozec L, de Leeuw NH, Birch HL.','Glucosepane is associated with changes to structural and physical properties of collagen fibrils','10.1016/j.mbplus.2019.100013','Examines how age-associated glucosepane cross-links relate to the structure and physical behaviour of collagen.'),
('2015','Matrix Biology','Co-author','Collier TA, Nash A, Birch HL, de Leeuw NH.','Preferential sites for intramolecular glucosepane cross-link formation in type I collagen: A thermodynamic study','10.1016/j.matbio.2015.06.001','Investigates the energetic preference for glucosepane cross-link formation at different sites within collagen.'),
