publications = f'''<header class="page-intro"><h1>Selected publications</h1><p class="lead">Eight selected journal articles spanning computational chemistry, extracellular-matrix biology, antifungal resistance and pain research.</p><p>First-author papers are marked below. This selection combines well-cited work with recent research and reflects the breadth of my contribution. <a href="{SCHOLAR}">Browse the complete record on Google Scholar.</a></p></header><ol class="publication-list">'''
for i,(year,journal,authorship,authors,title,doi,summary) in enumerate(PUBLICATIONS,1):
    publications += f'''<li><span class="pub-num" aria-hidden="true">{i:02}</span><article><div class="pub-top"><span>{escape(journal)} · {year}</span><span class="badge">{authorship}</span></div><h2><a href="https://doi.org/{doi}">{escape(title)}</a></h2><p class="authors">{escape(authors)}</p><p>{summary}</p><a class="paper-link" href="https://doi.org/{doi}">Read the article →</a></article></li>'''
publications += f'''</ol><section class="section"><p class="eyebrow">Independent research · Preprint</p><h2>Molecular Space-Time</h2><p class="reading">My recent preprint investigates predictive information and complex dynamics in molecular graph cellular automata. It is presented separately from the journal articles above.</p><div class="actions"><a href="{MANUSCRIPT}">Abstract and manuscript →</a><a href="{MANUSCRIPT}molecular-space-time.pdf">Read the PDF →</a></div></section>'''

research = '''<header class="page-intro"><h1>Research interests and projects</h1><p class="lead">My research interests connect theoretical biophysics, physics-based computational chemistry and the emergence of complex behaviour through local interactions.</p></header><section class="research-block" id="chemistry"><h2>Molecular and quantum chemistry</h2><p>My interests include molecular dynamics, quantum chemistry and fragment molecular orbital analysis of open- and closed-shell systems, alongside methods for describing strongly correlated electronic systems. I am particularly interested in how computational methods can clarify the physical basis of molecular behaviour.</p></section><section class="research-block" id="metalloproteases"><h2>Metalloproteases and the extracellular matrix</h2><p>My biological interests centre on matrix metalloproteases, particularly MMP1 and the membrane-anchored MMP14, together with membrane-protein interactions and lipid bilayer modelling.</p><h3>Collagen remodelling in osteogenesis imperfecta</h3><p>This project examines how changes in collagen structure affect its interaction with MMP1. It uses molecular simulation to investigate structural questions motivated by osteogenesis imperfecta, while keeping molecular observations distinct from claims about disease causation.</p><a href="https://github.com/acnash/mmp1-collagen-oi-adaptive-md">Explore the collagen research repository →</a></section><section class="research-block" id="complexity"><h2>Complexity and molecular space-time</h2><p>My interest in complexity theory has led me to fractal geometry, Lindenmayer systems and <a href="https://github.com/acnash/Strange-Matter-Engine">cellular automata</a>. I explore how these mathematical ideas connect with chemistry and the life sciences, particularly how local interactions generate organised behaviour across a larger system.</p><h3>Strange Matter Engine</h3><p>Molecular graph cellular automata pass numerical information between bonded atoms. Retaining the evolving states produces molecular space-time trajectories, which we can study as dynamical systems and use to construct predictive features.</p><div class="actions"><a href="https://github.com/acnash/Strange-Matter-Engine">Explore the repository →</a><a href="https://acnash.github.io/Strange-Matter-Engine/">Read the manuscript →</a></div><div class="wide-video">''' + video() + '''</div></section><section class="section"><h2>Code and publications</h2><div class="actions"><a href="https://github.com/acnash?tab=repositories">Browse all public repositories →</a><a href="publications.html">Selected publications →</a></div></section>'''

page('index.html','Scientific leadership & computational chemistry','Dr Anthony Nash: fractional scientific leadership, consultancy and hands-on computational research in drug discovery and the life sciences.',home)
